"use client";
import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { Trash2, Plus, Layout, Loader2 } from "lucide-react";

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [data, setData] = useState<any>(null);
  const [newColumn, setNewColumn] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/admin/stats")
      .then((res) => res.json())
      .then((resData) => {
        setData(resData);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  // KULLANICI SİLME
  const deleteUser = async (id: string) => {
    if (!confirm("Bu kullanıcıyı silmek istediğine emin misin?")) return;
    const res = await fetch(`/api/admin/users/${id}`, { method: "DELETE" });
    if (res.ok) {
      setData({ ...data, stats: data.stats.filter((u: any) => u.id !== id) });
    }
  };

  const addColumn = async () => {
    if (!newColumn) return;
    const res = await fetch("/api/admin/columns", {
      method: "POST",
      body: JSON.stringify({ name: newColumn }),
    });
    if (res.ok) {
      alert("Aşama eklendi!");
      setNewColumn("");
    }
  };

  // 1. KORUMA: Yükleme ekranı
  if (loading || !data) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <Loader2 className="w-10 h-10 text-fuchsia-500 animate-spin" />
        <p className="text-teal-400 font-black tracking-widest animate-pulse uppercase">Veriler Çekiliyor...</p>
      </div>
    );
  }

  // 2. KORUMA: Dizileri güvenli hale getir (Hata veren yer burasıydı)
  const stats = data?.stats || [];
  const messages = data?.messages || [];

  return (
    <div className="space-y-10 pb-20 animate-in fade-in duration-500">
      <header>
        <h1 className="text-4xl font-black text-fuchsia-500 uppercase italic">Admin Konsolu</h1>
        <p className="text-teal-400/50 text-xs tracking-widest uppercase">God Mode Aktif</p>
      </header>

      {/* SÜREÇ YÖNETİMİ */}
      <div className="bg-[#0E153A] border border-fuchsia-500/20 p-8 rounded-[2.5rem] shadow-2xl">
        <div className="flex items-center gap-3 mb-6">
          <Layout className="text-fuchsia-400" />
          <h2 className="text-xl font-bold text-white uppercase italic">İş Akışı (Review/Retro) Ekle</h2>
        </div>
        <div className="flex gap-4">
          <input 
            value={newColumn}
            onChange={(e) => setNewColumn(e.target.value)}
            placeholder="Aşama adı..."
            className="flex-1 bg-black/40 border border-teal-400/20 p-4 rounded-2xl text-white outline-none focus:border-fuchsia-500"
          />
          <button onClick={addColumn} className="bg-fuchsia-600 px-8 rounded-2xl text-white font-black uppercase hover:bg-fuchsia-500 transition-all">
            Ekle
          </button>
        </div>
      </div>

      {/* KULLANICI LİSTESİ */}
      <div className="bg-[#0E153A]/50 border border-teal-400/10 rounded-[2.5rem] overflow-hidden">
        <div className="p-6 bg-teal-400/5 border-b border-teal-400/10 text-teal-400 font-bold uppercase text-xs tracking-widest">
          Kullanıcı Yönetimi
        </div>
        <div className="divide-y divide-white/5">
          {stats.length > 0 ? (
            stats.map((user: any) => (
              <div key={user.id} className="p-6 flex items-center justify-between hover:bg-white/5 transition-all group">
                <div className="flex-1">
                  <h3 className="text-white font-bold">{user.name || "İsimsiz"}</h3>
                  <p className="text-[10px] text-teal-500/50 uppercase">{user.email}</p>
                </div>
                <div className="flex items-center gap-6">
                  <span className="text-fuchsia-400 font-black italic">{user.percentage}%</span>
                  <button 
                    onClick={() => deleteUser(user.id)}
                    className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))
          ) : (
            <div className="p-10 text-center text-white/20 uppercase text-xs">Kullanıcı bulunamadı.</div>
          )}
        </div>
      </div>

      {/* MESAJLAR */}
      <div className="bg-[#0E153A]/30 border border-teal-400/10 rounded-[2.5rem] p-6">
          <h3 className="text-teal-400 font-bold uppercase text-xs mb-4">Mesajlar</h3>
          {messages.map((m: any) => (
              <div key={m.id} className="mb-4 p-4 border-l-2 border-fuchsia-500 bg-white/5">
                  <p className="text-white font-bold text-sm">{m.name}</p>
                  <p className="text-white/60 text-xs">{m.message}</p>
              </div>
          ))}
      </div>
    </div>
  );
}